func TestPrintCSVItemsUnwrap(t *testing.T) {
	t.Parallel()
	envelope := json.RawMessage(`{"command":"plan reservation list","target_key":"abc","kind":"lodging","items":[{"day":1,"block_id":"b1","name":"Hotel"},{"day":2,"block_id":"b2","name":"Inn"}]}`)
	var buf bytes.Buffer
	if err := printCSV(&buf, envelope); err != nil {
		t.Fatalf("printCSV: %v", err)
	}
	got := buf.String()
	if strings.Contains(got, "command") || strings.Contains(got, "target_key") {
		t.Fatalf("csv should unwrap items, got %q", got)
	}
	if !strings.Contains(got, "block_id,day,name") {
		t.Fatalf("missing sorted header, got %q", got)
	}
	if !strings.Contains(got, "b1,1,Hotel") || !strings.Contains(got, "b2,2,Inn") {
		t.Fatalf("missing item rows, got %q", got)
	}

	buf.Reset()
	if err := printCSV(&buf, json.RawMessage(`[{"id":"a","name":"x"}]`)); err != nil {
		t.Fatalf("bare array: %v", err)
	}
	if !strings.Contains(buf.String(), "id,name") || !strings.Contains(buf.String(), "a,x") {
		t.Fatalf("bare array csv = %q", buf.String())
	}

	buf.Reset()
	obj := json.RawMessage(`{"command":"plan reservation list","count":0}`)
	if err := printCSV(&buf, obj); err != nil {
		t.Fatalf("object without items: %v", err)
	}
	if strings.TrimSpace(buf.String()) != string(obj) {
		t.Fatalf("non-list object should dump JSON, got %q", buf.String())
	}
}

func TestShortHelpOmitsGlobalFlags(t *testing.T) {
	t.Parallel()
	root := newRootCmd(&rootFlags{})
	leaf, _, err := root.Find([]string{"doctor"})
	if err != nil {
		t.Fatalf("find doctor: %v", err)
	}
	var buf bytes.Buffer
	writeShortHelp(&buf, leaf)
	got := buf.String()
	if strings.Contains(got, "Global Flags") {
		t.Fatalf("short help dumped Global Flags:\n%s", got)
	}
	if strings.Contains(got, "--rate-limit") {
		t.Fatalf("short help dumped global --rate-limit:\n%s", got)
	}
	if !strings.Contains(got, "Usage:") || !strings.Contains(got, "Check CLI health") {
		t.Fatalf("short help missing Use/Short:\n%s", got)
	}
	if !strings.Contains(got, "--fail-on") {
		t.Fatalf("short help missing local flags:\n%s", got)
	}
	if !strings.Contains(got, "--help-all") {
		t.Fatalf("short help missing --help-all pointer:\n%s", got)
	}
}

func TestHelpAllShowsGlobalFlags(t *testing.T) {
	t.Parallel()
	cmd := newRootCmd(&rootFlags{})
	var buf bytes.Buffer
	cmd.SetOut(&buf)
	cmd.SetErr(&buf)
	cmd.SetArgs([]string{"doctor", "--help-all"})
	if err := cmd.Execute(); err != nil {
		t.Fatalf("doctor --help-all: %v", err)
	}
	got := buf.String()
	if !strings.Contains(got, "Global Flags:") && !strings.Contains(got, "--rate-limit") {
		t.Fatalf("expected global flags in --help-all, got:\n%s", got)
	}
}

func TestCompactAndAgentFlagHelp(t *testing.T) {
	t.Parallel()
	cmd := newRootCmd(&rootFlags{})
	compact := cmd.PersistentFlags().Lookup("compact")
	if compact == nil {
		t.Fatal("missing --compact")
	}
	if !strings.Contains(compact.Usage, "Does not shrink object GETs") {
		t.Errorf("--compact help = %q, want honesty about object GETs", compact.Usage)
	}
	if !strings.Contains(compact.Usage, "plan outline") {
		t.Errorf("--compact help = %q, want plan outline", compact.Usage)
	}
	agent := cmd.PersistentFlags().Lookup("agent")
	if agent == nil {
		t.Fatal("missing --agent")
	}
	if !strings.Contains(agent.Usage, "plan outline") {
		t.Errorf("--agent help = %q, want plan outline", agent.Usage)
	}
	if !strings.Contains(agent.Usage, "does not strip tripPlan") {
		t.Errorf("--agent help = %q, want tripPlan honesty", agent.Usage)
	}
}
